"""server.py  --  the small web server behind the Front Desk page.   >>> YOU DO NOT EDIT THIS FILE <<<

It uses only Python's built-in web server, so there is nothing extra to install.
It does THREE things:
  1. POST /api/runs               starts the AskIT agent in the background and returns a run id
  2. GET  /api/runs/<id>/stream   CHAT view: sends each event the moment it happens (Server-Sent Events, "SSE")
  3. GET  /api/runs/<id>          TASK view: returns the progress so far, the page asks again every few seconds ("polling")
Both views read the SAME run, so the agent code is written once.
"""
import json
import sys
import threading
import time
import uuid
import webbrowser
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))

import fd_agent                    # noqa: E402
import model_factory as mf         # noqa: E402

RUNS = {}
LOCK = threading.Lock()
STATS = {"runs_started": 0, "cost_usd": 0.0, "polls": 0, "stream_opens": 0}


class Run:
    def __init__(self, question, provider, chaos):
        self.id = uuid.uuid4().hex[:8]
        self.question, self.provider, self.chaos = question, provider, chaos
        self.events, self.status, self.dropped, self.cancel = [], "running", False, False
        self.created = time.time()

    def emit(self, type_, **data):
        with LOCK:
            self.events.append({"id": len(self.events), "type": type_, "t": round(time.time() - self.created, 2), **data})
            if type_ == "final":
                self.status = "done"
                STATS["cost_usd"] += data.get("cost_usd", 0)
            elif type_ == "error":
                self.status = "error"

    def work(self):
        fd_agent.run(self.question, self.provider, self.chaos, self.emit, cancelled=lambda: self.cancel)
        if self.status == "running":                       # safety net: always end in a final state
            self.status = "error"


def progress(run):
    """Turn raw events into the checklist the TASK view shows."""
    steps, text = [], ""
    for e in run.events:
        t = e["type"]
        if t == "model_start":
            steps.append({"label": f"Ask the AI model (call {e['n']})", "state": "running"})
            text = ""
        elif t == "model_end" and steps:
            steps[-1].update(state="done", ms=e["ms"])
        elif t == "tool_start":
            steps.append({"label": f"Run tool {e['name']}", "state": "running"})
        elif t == "tool_end" and steps:
            steps[-1].update(state="done" if e["ok"] else "failed", ms=e["ms"])
        elif t == "token":
            text += e["text"]
    return steps, text


class Handler(BaseHTTPRequestHandler):
    def log_message(self, *a):                             # quiet terminal
        pass

    def _json(self, obj, code=200):
        body = json.dumps(obj, ensure_ascii=False).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        path, _, query = self.path.partition("?")
        q = dict(p.split("=", 1) for p in query.split("&") if "=" in p)
        if path in ("/", "/index.html"):
            body = (HERE / "ui" / "index.html").read_bytes()
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
        elif path == "/api/providers":
            st = mf.status()
            self._json({"auto": mf.auto_provider(), "providers": {k: {"ready": v[0], "note": v[1], "label": mf.LABELS[k]} for k, v in st.items()}})
        elif path == "/api/stats":
            self._json(STATS)
        elif path.startswith("/api/runs/") and path.endswith("/stream"):
            self._stream(path.split("/")[3], q)
        elif path.startswith("/api/runs/"):
            self._poll(path.split("/")[3])
        else:
            self._json({"error": "not found"}, 404)

    def do_POST(self):
        n = int(self.headers.get("Content-Length") or 0)
        data = json.loads(self.rfile.read(n) or b"{}") if n else {}
        if self.path == "/api/runs":
            provider = data.get("provider") or mf.auto_provider()
            run = Run(str(data.get("question", ""))[:500], provider, data.get("chaos") or {})
            with LOCK:
                RUNS[run.id] = run
                STATS["runs_started"] += 1
            threading.Thread(target=run.work, daemon=True).start()
            self._json({"run_id": run.id, "provider": provider, "model": mf.model_label(provider)})
        elif self.path.startswith("/api/runs/") and self.path.endswith("/cancel"):
            run = RUNS.get(self.path.split("/")[3])
            if run:
                run.cancel = True
            self._json({"ok": True})
        elif self.path == "/api/reset":
            with LOCK:
                RUNS.clear()
                STATS.update(runs_started=0, cost_usd=0.0, polls=0, stream_opens=0)
            self._json({"ok": True})
        else:
            self._json({"error": "not found"}, 404)

    # ---------------------------------------------------------------------------------------- CHAT view: Server-Sent Events
    def _stream(self, run_id, q):
        run = RUNS.get(run_id)
        if not run:
            return self._json({"error": "unknown run"}, 404)
        start = int(self.headers.get("Last-Event-ID") or q.get("from") or 0)
        with LOCK:
            STATS["stream_opens"] += 1
        self.send_response(200)
        self.send_header("Content-Type", "text/event-stream; charset=utf-8")
        self.send_header("Cache-Control", "no-cache")
        self.send_header("Connection", "close")
        self.end_headers()
        i, sent = start, 0
        try:
            while True:
                with LOCK:
                    batch = run.events[i:]
                    finished = run.status != "running"
                for e in batch:
                    self.wfile.write(f"id: {e['id'] + 1}\nevent: {e['type']}\ndata: {json.dumps(e, ensure_ascii=False)}\n\n".encode("utf-8"))
                    self.wfile.flush()
                    i, sent = e["id"] + 1, sent + 1
                    if run.chaos.get("drop") and not run.dropped and sent >= 6 and run.status == "running":
                        run.dropped = True                  # BREAK-IT: cut the connection in the middle of the answer, once
                        return
                if finished and i >= len(run.events):
                    return
                time.sleep(0.05)
        except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
            return

    # ---------------------------------------------------------------------------------------- TASK view: ask for progress
    def _poll(self, run_id):
        run = RUNS.get(run_id)
        if not run:
            return self._json({"error": "unknown run"}, 404)
        with LOCK:
            STATS["polls"] += 1
        steps, text = progress(run)
        final = next((e for e in run.events if e["type"] == "final"), None)
        err = next((e for e in run.events if e["type"] == "error"), None)
        self._json({"run_id": run.id, "status": run.status, "elapsed": round(time.time() - run.created, 1), "steps": steps,
                    "partial": text if run.status == "running" else "", "final": final, "error": err, "question": run.question})


def main():
    port = 8014
    server = None
    while server is None and port < 8030:
        try:
            server = ThreadingHTTPServer(("127.0.0.1", port), Handler)      # 127.0.0.1 = only YOUR computer can open it
        except OSError:
            port += 1
    if server is None:
        print("Could not open a port between 8014 and 8029. Close other labs and try again.")
        return 1
    server.daemon_threads = True
    url = f"http://127.0.0.1:{port}"
    print(f"\nFront Desk is running.  Open this address in your browser:  {url}")
    print("Keep this window open. Stop with Ctrl+C.\n")
    threading.Timer(1.0, lambda: webbrowser.open(url)).start()
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    return 0


if __name__ == "__main__":
    sys.exit(main())
